questionvariables.text:
a1:rand_with_step(40,70,10);
a2:rand_with_step(10,30,10);
a3:rand_with_step(30,50,10);
a4:rand_with_step(20,50,10);
a5:rand_with_step(20,60,10);
a6:rand_with_step(10,30,10);
a7:rand_with_step(10,30,10);
a8:a5-10;
Tot:a1+a2+a3+a4+a5+a6+a7+a8; /*Total number of students*/
num_n:a8; /*number of students who studied none of the subjects*/
num_M:a1+a2+a4+a5;/*number of students who studied Mathematics*/
num_P:a2+a3+a5+a6;/*number of students who studied Physics*/
num_C:a4+a5+a6+a7;/*number of students who studied Chemistry*/
num_mnp:a2+a5;/*number of students who studied Mathematics and Physics*/
num_pnc:a5+a6;/*number of students who studied Physics and Chemistry*/
num_mnc:a4+a5;/*number of students who studied Chemistry and Mathematics*/
MuPuC:Tot-num_n;
ta:a5;
